const handleTuteurChange = (groupe, tuteurId) => {
  if (!tuteurId || typeof tuteurId !== "string") {
    console.error("ID du tuteur invalide :", tuteurId);
    return;
  }

  const updatedGroupes = groupes.map(g => {
    if (g.idGroupe === groupe.idGroupe) {
      const updatedTuteur = tuteurs.find(t => t.idTuteur === tuteurId); // Assurez-vous que tuteurId est une chaîne
      return {
        ...g,
        tuteur: updatedTuteur || null,
      };
    }
    return g;
  });
  setGroupes(updatedGroupes);
};

const handleSujetChange = (groupe, sujetId) => {
  if (!sujetId || isNaN(sujetId)) {
    console.error("ID du sujet invalide :", sujetId);
    return;
  }

  const updatedGroupes = groupes.map(g => {
    if (g.idGroupe === groupe.idGroupe) {
      const updatedSujet = sujets.find(s => s.idSujet === parseInt(sujetId)); // Conversion en entier
      return {
        ...g,
        sujet: updatedSujet || null,
      };
    }
    return g;
  });
  setGroupes(updatedGroupes);
};

